def compute_consensus(observers):
    if not observers:
        return frozenset()
    result = set(observers[0])
    for t in observers[1:]:
        result &= set(t)
    return frozenset(result)

def compute_spn(tau, all_tops, max_n=10):
    finer = [t for t in all_tops if set(tau) < set(t)]
    if not finer: return 0
    for n in range(2, min(max_n, len(finer))+1):
        for combo in combinations(finer, n):
            if compute_consensus(list(combo)) == tau:
                return n
    return 0

def phantom_spectrum(observers, consensus, X):
    spectrum = {x: set() for x in X}
    for i, t in enumerate(observers):
        for U in set(t) - set(consensus):
            for x in U:
                spectrum[x].add(i)
    return spectrum
